"""Main window for Lab 08 (fixed infrastructure - students do not edit this file)."""
from __future__ import annotations

from PyQt6.QtCore import QSettings, QSize, Qt
from PyQt6.QtGui import QKeySequence, QShortcut
from PyQt6.QtWidgets import (
    QApplication,
    QFrame,
    QHBoxLayout,
    QLabel,
    QMainWindow,
    QPushButton,
    QStackedWidget,
    QVBoxLayout,
    QWidget,
)

from config import (
    APP_NAME,
    CUSTOM_MODEL_PATH,
    DEFAULT_SETTINGS_MESSAGE,
    DEFAULT_THEME,
    ORGANIZATION_NAME,
)
from dataset import DatasetStore
from gui_compare import ComparePage
from gui_dataset import DatasetPage
from gui_train import TrainPage
from styles import build_style

STEP_TITLES = ("1  Dataset Builder", "2  Train", "3  Before / After")


class AppWindow(QMainWindow):
    """Main interactive UI for Lab 08: build a dataset, fine-tune YOLO, compare."""

    def __init__(self):
        super().__init__()
        self.setWindowTitle(APP_NAME)
        self.setMinimumSize(QSize(1120, 740))
        self.resize(1500, 900)

        self.settings = QSettings(ORGANIZATION_NAME, APP_NAME)
        self.store = DatasetStore()
        self._closing = False
        self._dark = self.settings.value("theme", DEFAULT_THEME) == "dark"

        self._build_ui()
        self._build_shortcuts()
        self._apply_theme()
        self.settings_label.setText("Settings: Restored")
        if CUSTOM_MODEL_PATH.exists():
            self.compare_page.set_custom_weights(str(CUSTOM_MODEL_PATH))
        self._set_step(0)

    # ------------------------------------------------------------------ UI
    def _build_ui(self) -> None:
        central = QWidget()
        root = QVBoxLayout(central)
        root.setContentsMargins(14, 14, 14, 12)
        root.setSpacing(12)

        header = QFrame()
        header.setObjectName("Header")
        header_layout = QHBoxLayout(header)
        header_layout.setContentsMargins(18, 14, 18, 14)
        title_box = QVBoxLayout()
        title = QLabel("YOLO Fine-Tuning Studio")
        title.setObjectName("Title")
        subtitle = QLabel("Build your own mini detector: annotate your objects, fine-tune YOLO, compare before / after")
        subtitle.setObjectName("Subtitle")
        title_box.addWidget(title)
        title_box.addWidget(subtitle)
        header_layout.addLayout(title_box, 1)

        self.step_buttons: list[QPushButton] = []
        for index, text in enumerate(STEP_TITLES):
            button = QPushButton(text)
            button.setObjectName("step")
            button.setCheckable(True)
            button.clicked.connect(lambda _checked=False, i=index: self._set_step(i))
            header_layout.addWidget(button)
            self.step_buttons.append(button)
        header_layout.addSpacing(16)
        self.theme_button = QPushButton()
        self.theme_button.clicked.connect(self._toggle_theme)
        header_layout.addWidget(self.theme_button)
        self.reset_button = QPushButton("Reset")
        self.reset_button.setObjectName("danger")
        self.reset_button.setToolTip("Reset parameters to their defaults (the dataset is not touched)")
        self.reset_button.clicked.connect(self._reset_defaults)
        header_layout.addWidget(self.reset_button)
        root.addWidget(header)

        self.dataset_page = DatasetPage(self.store, self.settings)
        self.train_page = TrainPage(self.store, self.settings)
        self.compare_page = ComparePage(self.settings)
        self.pages = [self.dataset_page, self.train_page, self.compare_page]
        self.stack = QStackedWidget()
        for page in self.pages:
            self.stack.addWidget(page)
            page.status_changed.connect(self._show_status)
        self.compare_page.fps_changed.connect(lambda fps: self.fps_label.setText(f"FPS: {fps:.1f}"))
        self.dataset_page.dataset_changed.connect(self.train_page.refresh_summary)
        self.train_page.training_finished.connect(self._on_training_finished)
        self.train_page.go_to_compare.connect(lambda: self._set_step(2))
        root.addWidget(self.stack, 1)

        status = QFrame()
        status.setObjectName("StatusBar")
        status_layout = QHBoxLayout(status)
        status_layout.setContentsMargins(14, 8, 14, 8)
        self.status_label = QLabel("Ready.")
        self.status_label.setObjectName("Muted")
        self.settings_label = QLabel(DEFAULT_SETTINGS_MESSAGE)
        self.settings_label.setObjectName("MetricValue")
        self.fps_label = QLabel("FPS: --")
        self.fps_label.setObjectName("MetricValue")
        status_layout.addWidget(self.status_label, 1)
        status_layout.addWidget(self.settings_label)
        status_layout.addSpacing(18)
        status_layout.addWidget(self.fps_label)
        root.addWidget(status)

        self.setCentralWidget(central)
        for button in self.findChildren(QPushButton):
            button.setFocusPolicy(Qt.FocusPolicy.NoFocus)

    def _build_shortcuts(self) -> None:
        QShortcut(QKeySequence("R"), self, activated=self._reset_defaults)
        QShortcut(QKeySequence("T"), self, activated=self._toggle_theme)
        QShortcut(QKeySequence("Q"), self, activated=self.close)
        for index in range(3):
            QShortcut(QKeySequence(f"Ctrl+{index + 1}"), self, activated=lambda i=index: self._set_step(i))

    # --------------------------------------------------------------- steps
    def _set_step(self, index: int) -> None:
        for other, page in enumerate(self.pages):
            if other != index:
                page.deactivate()
        self.stack.setCurrentIndex(index)
        self.pages[index].activate()
        for other, button in enumerate(self.step_buttons):
            button.setChecked(other == index)
        self.status_label.setText(f"Step {index + 1}: {STEP_TITLES[index][3:]}")
        if index != 2:
            self.fps_label.setText("FPS: --")

    def _show_status(self, text: str) -> None:
        self.status_label.setText(text)

    def _on_training_finished(self, path: str) -> None:
        self.compare_page.set_custom_weights(path)
        self.status_label.setText("Training finished. Open Step 3 (Before / After) to see the result.")

    # --------------------------------------------------------------- theme
    def _apply_theme(self) -> None:
        self.setStyleSheet(build_style(self._dark))
        self.theme_button.setText("Light Theme" if self._dark else "Dark Theme")
        for page in self.pages:
            page.apply_theme(self._dark)

    def _toggle_theme(self) -> None:
        self._dark = not self._dark
        self._apply_theme()
        self._save_settings()

    # ------------------------------------------------------------ settings
    def _reset_defaults(self) -> None:
        if self.train_page.is_training():
            self.status_label.setText("Cannot reset parameters while training is running.")
            return
        for page in self.pages:
            page.reset_defaults()
        self._save_settings()
        self.status_label.setText("Parameters reset to defaults.")

    def _save_settings(self) -> None:
        self.settings.setValue("theme", "dark" if self._dark else "light")
        self.settings.sync()
        self.settings_label.setText("Settings: Saved")

    def closeEvent(self, event) -> None:
        if not self._closing:
            self._closing = True
            self._save_settings()
            for page in self.pages:
                page.shutdown()
        event.accept()


def create_application() -> QApplication:
    app = QApplication.instance()
    if app is None:
        app = QApplication([])
    app.setOrganizationName(ORGANIZATION_NAME)
    app.setApplicationName(APP_NAME)
    return app
